def num(n) = [:n, n]
def err(s) = [:e, s]
def to_number(x) = x.nil? ? num(0) : %i[s g].include?(x[0]) ? err("#VALUE!") : x
    @values = @contents.dup
  def evaluate(x)
    case x[0]
    when :n, :s, :g
      x
    when :r
      @values[idx(x)]
    when :u
      a = to_number(evaluate(x[1]))
      a[0] == :e ? a : num(-a[1])
    @values = @contents.map { |x| x&.first == :"=" ? nil : x }
